style.css:
/* Abyssal Dreamwave Style */

body {
    background: linear-gradient(180deg, #0a1f3a, #0f3c5e, #1e6f9f);
    color: #e0f7ff;
    font-family: "Segoe UI", sans-serif;
}

/* Soft glowing text */
h1, h2, h3 {
    color: #a8eaff;
    text-shadow: 0 0 8px rgba(168, 234, 255, 0.6);
}

/* Cards / containers */
div, section, article {
    background: rgba(15, 60, 94, 0.6);
    backdrop-filter: blur(10px);
    border-radius: 12px;
    border: 1px solid rgba(168, 234, 255, 0.2);
    box-shadow: 0 0 15px rgba(0, 150, 255, 0.2);
}

/* Buttons */
button {
    background: linear-gradient(135deg, #1e6f9f, #3bb7ff);
    color: white;
    border: none;
    border-radius: 8px;
    padding: 8px 16px;
    transition: 0.3s;
}

button:hover {
    background: linear-gradient(135deg, #3bb7ff, #6fe3ff);
    box-shadow: 0 0 10px rgba(111, 227, 255, 0.8);
}

/* Links */
a {
    color: #6fe3ff;
    text-decoration: none;
}

a:hover {
    text-shadow: 0 0 6px rgba(111, 227, 255, 0.8);
}

/* Scrollbar */
::-webkit-scrollbar {
    width: 8px;
}

::-webkit-scrollbar-track {
    background: #0a1f3a;
}

::-webkit-scrollbar-thumb {
    background: #3bb7ff;
    border-radius: 10px;
}

/* Subtle floating effect */
* {
    transition: all 0.2s ease-in-out;
}
